# quick stats of projected coordinate extents and text-like height
import re,numpy as np
from collections import defaultdict
path='/app/text.gcode';x=y=z=0.;obj=None;segs=defaultdict(list)
for ln,line in enumerate(open(path,errors='replace'),1):
 line=line.strip()
 if line.startswith('M486'):
  m=re.search(r'M486 S(-?\d+)',line)
  if m:
   s=int(m.group(1));obj=None if s==-1 else s
  continue
 if not (line.startswith('G0') or line.startswith('G1')):continue
 vals={}
 for w in line.split()[1:]:
  try:vals[w[0]]=float(w[1:])
  except:pass
 nx=vals.get('X',x);ny=vals.get('Y',y);nz=vals.get('Z',z);ne=vals.get('E',0.)
 if obj is not None and ne>0 and (abs(nx-x)>1e-9 or abs(ny-y)>1e-9):segs[obj].append((x,y,z,nx,ny,nz,ln))
 x,y,z=nx,ny,nz
for o in sorted(segs):
 pts=np.array([[s[0],s[1],s[2]] for s in segs[o]]+[[s[3],s[4],s[5]] for s in segs[o]])
 mean=pts.mean(0);w,v=np.linalg.eigh(np.cov((pts-mean).T))
 print(o, 'nseg',len(segs[o]),'mean',mean,'eig',w)
 print('v',v)
PY
